            if col != _background(grid): out.append((col,cells))
    return out

def _background(grid):
    from collections import Counter
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def _embedded(small, large):
    # Does the complete small pixel shape occur as a translated subset of large?
    anchors=set(large)
    sr=min(r for r,c in small); sc=min(c for r,c in small)
    shape=[(r-sr,c-sc) for r,c in small]
    for ar,ac in large:
        if all((ar+dr,ac+dc) in anchors for dr,dc in shape):
            return True
    return False

